using System.Text;

namespace TCPipeAutoDraw.UI.Studio
{
    internal static class CDBoxStudioSectionDrawingPage
    {
        public static string BuildEmbeddedSection()
        {
            return "<section id=\"sectionDrawingPage\" style=\"display:none\"></section>";
        }

        public static string BuildStandaloneDocument(CDBoxStudioSettings settings, string logFilePath)
        {
            settings = settings ?? new CDBoxStudioSettings();
            settings.Normalize();
            var html = new StringBuilder();
            html.Append("<!doctype html><html lang=\"zh-CN\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>CDBox Studio - 断面图生成</title><style>");
            html.Append(BuildStyles(true));
            html.Append("</style></head><body data-theme=\"").Append(Html(settings.Theme)).Append("\" class=\"").Append(settings.AnimationsEnabled ? string.Empty : "no-animations").Append("\"><section id=\"sectionDrawingPage\" style=\"height:100%\"></section><div id=\"sdToast\" class=\"sd-toast-host\"></div><script>");
            html.Append(BuildComponentScript());
            html.Append("function sdPost(n,a){try{chrome.webview.postMessage('studio|'+n+'|'+encodeURIComponent(a||''));}catch(ex){}}function sdToast(m,k){var h=document.getElementById('sdToast'),e=document.createElement('div');e.className='sd-toast '+(k||'info');e.textContent=m||'';h.appendChild(e);setTimeout(function(){e.classList.add('show');},10);setTimeout(function(){e.classList.remove('show');setTimeout(function(){e.remove();},180);},2800);}window.CDBoxStudioToast=sdToast;window.CDBoxSectionDrawingPage.create({rootId:'sectionDrawingPage',post:sdPost,toast:sdToast,standalone:true}).open();setTimeout(function(){sdPost('ready','section-drawing');},50);");
            html.Append("</script><span style=\"display:none\">").Append(Html(logFilePath)).Append("</span></body></html>");
            return html.ToString();
        }

        public static string BuildStyles(bool standalone)
        {
            string root = standalone
                ? @":root{--bg:#f5f7fb;--panel:#fff;--panel2:#f8fafc;--text:#172033;--muted:#64748b;--line:#dce5f1;--brand:#326fea;--brand2:#7c3aed;--danger:#b91c1c;--preview-bg:#101827;--preview-line:#e5edf8;--preview-muted:#91a4bd}body[data-theme='fresh']{--bg:#f2f6ff;--panel:#fff;--panel2:#edf4ff;--line:#d7e5ff}body[data-theme='dark']{--bg:#0f172a;--panel:#172033;--panel2:#111827;--text:#e5e7eb;--muted:#94a3b8;--line:#2b3a50;--brand:#60a5fa;--brand2:#a78bfa;--preview-bg:#080d18;--preview-line:#d7e5f5;--preview-muted:#8ba0bb}html,body{height:100%;margin:0;overflow:hidden;background:var(--bg);font-family:'Microsoft YaHei UI','Segoe UI',sans-serif;color:var(--text)}"
                : string.Empty;

            string styles = root + @"
#sectionDrawingPage{height:100%;min-height:0}.sd-page,.sd-page *{box-sizing:border-box}.sd-page{height:100%;min-height:680px;display:flex;flex-direction:column;gap:12px;padding:16px 18px 20px;overflow:hidden;background:linear-gradient(180deg,rgba(220,232,255,.50),transparent 240px),var(--bg);color:var(--text)}.sd-head{display:flex;align-items:center;justify-content:space-between;gap:16px;flex:0 0 auto}.sd-head h2{margin:0;font-size:24px}.sd-head small{margin-left:8px;color:var(--brand);font-size:12px}.sd-actions{display:flex;align-items:center;justify-content:flex-end;gap:7px;flex-wrap:wrap}.sd-btn{height:36px;border:1px solid var(--line);border-radius:10px;background:var(--panel);color:var(--text);padding:0 12px;font:inherit;font-weight:750;cursor:pointer;white-space:nowrap}.sd-btn:hover{transform:translateY(-1px);border-color:rgba(50,111,234,.45)}.sd-btn.primary{border:0;color:#fff;background:linear-gradient(135deg,var(--brand),var(--brand2));box-shadow:0 9px 20px rgba(50,111,234,.18)}.sd-btn.danger{color:var(--danger);border-color:#fecaca}.sd-btn.icon{width:34px;padding:0;font-size:17px}.sd-btn:disabled{opacity:.45;cursor:not-allowed;transform:none}.sd-work{display:grid;grid-template-columns:minmax(480px,570px) minmax(420px,1fr);gap:12px;min-height:0;flex:1 1 auto}.sd-editor{min-height:0;overflow:auto;padding-right:3px;scrollbar-width:thin}.sd-card{margin-bottom:10px;border:1px solid var(--line);border-radius:16px;background:var(--panel);box-shadow:0 10px 24px rgba(30,50,90,.055);overflow:hidden}.sd-card-head{display:flex;align-items:center;justify-content:space-between;gap:12px;padding:12px 14px;background:var(--panel2);border-bottom:1px solid var(--line)}.sd-card-head h3{margin:0;font-size:14px}.sd-card-body{padding:13px}.sd-fields{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:10px}.sd-field{min-width:0}.sd-field.wide{grid-column:span 2}.sd-field.full{grid-column:1/-1}.sd-field>span{display:block;margin-bottom:5px;color:var(--muted);font-size:11px;font-weight:750}.sd-field input[type=text],.sd-field input[type=number],.sd-field select{width:100%;height:36px;border:1px solid var(--line);border-radius:9px;background:var(--panel2);color:var(--text);padding:0 9px;font:inherit;outline:0}.sd-field input:focus,.sd-field select:focus,.sd-table input:focus,.sd-table select:focus{border-color:var(--brand);box-shadow:0 0 0 3px rgba(50,111,234,.10)}.sd-check-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:8px}.sd-check{min-height:34px;display:flex;align-items:center;gap:8px;color:var(--text);font-size:12px}.sd-check input{width:17px;height:17px;accent-color:var(--brand)}.sd-table-wrap{overflow:auto}.sd-table{width:100%;min-width:760px;border-collapse:separate;border-spacing:0}.sd-table th,.sd-table td{padding:7px;border-bottom:1px solid var(--line);font-size:12px;text-align:left;vertical-align:middle}.sd-table th{position:sticky;top:0;z-index:2;background:var(--panel2);color:var(--muted);font-weight:800}.sd-table tbody tr:last-child td{border-bottom:0}.sd-table input[type=text],.sd-table input[type=number],.sd-table select{width:100%;height:32px;border:1px solid var(--line);border-radius:8px;background:var(--panel2);color:var(--text);padding:0 7px;font:inherit;outline:0}.sd-table input[type=checkbox]{width:17px;height:17px;accent-color:var(--brand)}.sd-drag{width:28px;text-align:center;color:var(--muted);font-size:17px;cursor:grab;user-select:none}.sd-layer-row.dragging,.sd-pipe-row.dragging{opacity:.42}.sd-layer-row.drag-over td,.sd-pipe-row.drag-over td{background:rgba(50,111,234,.08)}.sd-mini{border:1px solid var(--line);border-radius:8px;background:var(--panel);color:var(--text);height:30px;padding:0 8px;font:inherit;font-size:11px;cursor:pointer}.sd-mini.danger{color:var(--danger);border-color:#fecaca}.sd-empty-row{text-align:center!important;color:var(--muted);padding:18px!important}.sd-preview-card{position:relative;min-height:0;display:flex;flex-direction:column;border:1px solid #24344a;border-radius:18px;overflow:hidden;background:var(--preview-bg);box-shadow:0 18px 42px rgba(15,23,42,.18)}.sd-preview-head{height:48px;display:flex;align-items:center;justify-content:space-between;gap:12px;padding:0 13px;border-bottom:1px solid rgba(148,163,184,.18);color:var(--preview-line);flex:0 0 auto}.sd-preview-head strong{font-size:13px}.sd-preview-meta{color:var(--preview-muted);font-size:11px}.sd-preview-tools{display:flex;align-items:center;gap:6px}.sd-preview-tools button{width:30px;height:30px;border:1px solid rgba(148,163,184,.25);border-radius:8px;background:rgba(255,255,255,.05);color:var(--preview-line);cursor:pointer}.sd-preview-tools button.fit{width:auto;padding:0 10px}.sd-preview-stage{position:relative;min-height:0;flex:1 1 auto;overflow:hidden;background-color:var(--preview-bg);background-image:linear-gradient(rgba(148,163,184,.055) 1px,transparent 1px),linear-gradient(90deg,rgba(148,163,184,.055) 1px,transparent 1px);background-size:24px 24px}.sd-preview-stage svg{width:100%;height:100%;display:block;touch-action:none;cursor:grab}.sd-preview-stage svg.panning{cursor:grabbing}.sd-preview-stage text{font-family:'Microsoft YaHei UI','Segoe UI',sans-serif;user-select:none}.sd-preview-stage .outline{fill:none;stroke:var(--preview-line);stroke-width:1.5;vector-effect:non-scaling-stroke}.sd-preview-stage .label-box{fill:rgba(15,23,42,.34);stroke:var(--preview-line);stroke-width:1.2;vector-effect:non-scaling-stroke}.sd-preview-stage .label-text,.sd-preview-stage .pipe-text{fill:var(--preview-line);font-size:12px;text-anchor:middle;dominant-baseline:middle}.sd-preview-stage .pipe{fill:var(--preview-bg);stroke:#7dd3fc;stroke-width:2;vector-effect:non-scaling-stroke}.sd-preview-stage .pipe-text{font-size:10px;fill:#bae6fd}.sd-preview-stage .dim{fill:none;stroke:var(--preview-muted);stroke-width:1;vector-effect:non-scaling-stroke}.sd-preview-stage .dim-text{fill:var(--preview-muted);font-size:10px;text-anchor:middle;dominant-baseline:middle;paint-order:stroke;stroke:var(--preview-bg);stroke-width:5px}.sd-preview-stage .title-text{fill:var(--preview-line);font-size:15px;font-weight:800;text-anchor:middle}.sd-preview-stage .origin{fill:#60a5fa}.sd-modal-backdrop{display:none;position:fixed;z-index:1200;inset:0;background:rgba(15,23,42,.40);backdrop-filter:blur(4px);align-items:center;justify-content:center;padding:22px}.sd-modal-backdrop.show{display:flex}.sd-modal{width:min(760px,100%);max-height:min(680px,90vh);display:flex;flex-direction:column;border:1px solid var(--line);border-radius:17px;background:var(--panel);box-shadow:0 24px 70px rgba(15,23,42,.25);overflow:hidden}.sd-modal-head,.sd-modal-foot{display:flex;align-items:center;justify-content:space-between;gap:10px;padding:13px 15px;background:var(--panel2)}.sd-modal-head{border-bottom:1px solid var(--line)}.sd-modal-head h3{margin:0;font-size:15px}.sd-modal-body{overflow:auto}.sd-modal-foot{border-top:1px solid var(--line);justify-content:flex-end}.sd-toast-host{position:fixed;right:22px;bottom:22px;display:grid;gap:8px;z-index:1500}.sd-toast{opacity:0;transform:translateY(8px);padding:11px 14px;border-radius:12px;background:#172033;color:#fff;transition:.18s}.sd-toast.show{opacity:1;transform:none}.sd-toast.success{background:#047857}.sd-toast.error{background:#b91c1c}.sd-page.embedded{height:calc(100vh - 76px)}.no-animations *{animation:none!important;transition:none!important}@media(max-width:1250px){.sd-work{grid-template-columns:minmax(430px,520px) minmax(380px,1fr)}.sd-fields{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:980px){.sd-page{overflow:auto}.sd-work{display:flex;flex-direction:column;overflow:visible}.sd-editor{overflow:visible}.sd-preview-card{min-height:620px}.sd-head{align-items:flex-start;flex-direction:column}.sd-actions{justify-content:flex-start}.sd-page.embedded{height:auto;min-height:1200px}}@media(max-width:620px){.sd-fields,.sd-check-grid{grid-template-columns:1fr}.sd-field.wide{grid-column:auto}.sd-preview-card{min-height:500px}}
.sd-page{--preview-bg:#101827;--preview-line:#e5edf8;--preview-muted:#91a4bd}.sd-dirty{display:none;color:#f59e0b}.sd-dirty.show{display:inline}.sd-preview-stage .body-box{stroke:var(--preview-line);stroke-width:1.5;vector-effect:non-scaling-stroke}
";
            styles = styles.Replace("grid-template-columns:minmax(480px,570px) minmax(420px,1fr)", "grid-template-columns:minmax(0,1fr) 460px");
            styles = styles.Replace("@media(max-width:1250px){.sd-work{grid-template-columns:minmax(430px,520px) minmax(380px,1fr)}", "@media(max-width:1250px){");
            styles += ".sd-field textarea{width:100%;min-height:72px;resize:vertical;border:1px solid var(--line);border-radius:9px;background:var(--panel2);color:var(--text);padding:8px 9px;font:inherit;outline:0}.sd-field textarea:focus{border-color:var(--brand);box-shadow:0 0 0 3px rgba(50,111,234,.10)}.sd-card{border-radius:12px}.sd-preview-card,.sd-modal{border-radius:13px}";
            return styles;
        }

        public static string BuildComponentScript()
        {
            string script = @"
(function(w){
var instances=[];
function esc(v){return String(v==null?'':v).replace(/[&<>']/g,function(c){return {'&':'&amp;','<':'&lt;','>':'&gt;',""'"":'&#39;'}[c]||c;});}
function clone(v){return JSON.parse(JSON.stringify(v||{}));}
function num(v,d){var n=Number(v);return isFinite(n)?n:(d||0);}
function fmt(v){var n=num(v,0);return String(Number(n.toFixed(10)));}
function pipeText(d){return 'DN'+Math.round(Math.max(0,num(d,0))*1000);}
function Editor(o){this.cfg=o||{};this.root=document.getElementById(this.cfg.rootId||'sectionDrawingPage');this.options=null;this.defaults=null;this.catalog={textStyles:[],dimensionStyles:[],layerNames:[],hatchPatterns:[]};this.activeLayer=-1;this.dirty=false;this.zoom=1;this.panX=0;this.panY=0;this.dragLayer=-1;this.dragPipe=-1;}
Editor.prototype.post=function(n,a){if(this.cfg.post)this.cfg.post(n,a||'');};
Editor.prototype.toast=function(m,k){if(this.cfg.toast)this.cfg.toast(m,k||'info');};
Editor.prototype.open=function(){this.post('getSectionDrawingOptions','');return this;};
Editor.prototype.suspend=function(){return this;};
Editor.prototype.load=function(ctx){ctx=ctx||{};this.options=clone(ctx.options||ctx.Options||{});this.defaults=clone(ctx.defaults||ctx.Defaults||this.options);this.catalog={textStyles:clone(ctx.textStyles||ctx.TextStyles||[]),dimensionStyles:clone(ctx.dimensionStyles||ctx.DimensionStyles||[]),layerNames:clone(ctx.layerNames||ctx.LayerNames||[]),hatchPatterns:clone(ctx.hatchPatterns||ctx.HatchPatterns||[])};this.normalize();this.dirty=false;this.render();};
Editor.prototype.normalize=function(){var o=this.options||(this.options={});if(!Array.isArray(o.Layers)||!o.Layers.length)o.Layers=[{DrawLayer:true,LeftLabel:'自定义层',Height:.1,HeightLocked:false,HatchPatternName:'',HatchScale:1,HatchAngle:0,Pipes:[]}];o.Width=Math.max(.01,num(o.Width,1));o.TextHeight=Math.max(.001,num(o.TextHeight,.08));o.LeftLabelWidth=Math.max(.2,num(o.LeftLabelWidth,.45));o.TopDimensionOffset=Math.max(0,num(o.TopDimensionOffset,.08));o.BottomDimensionOffset=Math.max(0,num(o.BottomDimensionOffset,.08));o.RightDimensionOffset=Math.max(0,num(o.RightDimensionOffset,.08));o.TitleOffset=Math.max(0,num(o.TitleOffset,.12));o.Layers.forEach(function(l,i){if(!l)l=o.Layers[i]={};if(l.DrawLayer==null)l.DrawLayer=true;l.Height=Math.max(.001,num(l.Height,.1));l.HatchScale=Math.max(0,num(l.HatchScale,1));l.HatchAngle=0;if(!Array.isArray(l.Pipes))l.Pipes=[];l.Pipes.forEach(function(p){p.Diameter=Math.max(.001,num(p.Diameter,.3));p.HostLayerIndex=i;if(p.VerticalMode==null)p.VerticalMode=1;if(!p.PipeText)p.PipeText=pipeText(p.Diameter);});});this.syncTotal();};
Editor.prototype.syncTotal=function(){if(!this.options)return;var total=this.options.Layers.reduce(function(s,l){return s+(l&&l.DrawLayer?num(l.Height,0):0);},0);if(!this.options.LockTotalHeight||num(this.options.TotalHeight,0)<=0)this.options.TotalHeight=total;};
Editor.prototype.rebalanceHeights=function(changedIndex){var o=this.options;if(!o||!o.LockTotalHeight)return this.syncTotal();var layers=o.Layers||[],target=Math.max(.001,num(o.TotalHeight,0)),fixed=0,adjustable=[];layers.forEach(function(l,i){if(!l||!l.DrawLayer)return;var h=Math.max(.001,num(l.Height,.1));l.Height=h;if(i===changedIndex||l.HeightLocked)fixed+=h;else adjustable.push({layer:l,height:h});});if(!adjustable.length){var changed=layers[changedIndex];if(changed&&changed.DrawLayer&&!changed.HeightLocked){var other=layers.reduce(function(s,l,i){return s+(i!==changedIndex&&l&&l.DrawLayer?num(l.Height,0):0);},0);changed.Height=Math.max(.001,target-other);}var activeTotal=layers.reduce(function(s,l){return s+(l&&l.DrawLayer?num(l.Height,0):0);},0);if(activeTotal>0)o.TotalHeight=activeTotal;return;}var minimum=fixed+adjustable.length*.001;if(target<minimum){target=minimum;o.TotalHeight=target;}var remaining=target-fixed,weight=adjustable.reduce(function(s,x){return s+x.height;},0),used=0;adjustable.forEach(function(x,i){var h=i===adjustable.length-1?remaining-used:(weight>0?remaining*x.height/weight:remaining/adjustable.length);h=Math.max(.001,h);x.layer.Height=h;used+=h;});o.TotalHeight=layers.reduce(function(s,l){return s+(l&&l.DrawLayer?num(l.Height,0):0);},0);};
Editor.prototype.refreshHeightInputs=function(skip){var self=this;[].slice.call(this.root.querySelectorAll('[data-layer-row]')).forEach(function(row){var i=Number(row.getAttribute('data-layer-row')),input=row.querySelector('[data-layer-field=Height]');if(input&&!(input===skip&&document.activeElement===skip)&&self.options.Layers[i])input.value=fmt(self.options.Layers[i].Height);});var total=this.root.querySelector('[data-field=TotalHeight]');if(total&&!(total===skip&&document.activeElement===skip))total.value=fmt(this.options.TotalHeight);};
Editor.prototype.selectOptions=function(items,value){var values=Array.isArray(items)?items.slice():[],wanted=String(value||'').toLowerCase(),found=false;values.forEach(function(x){if(String(x).toLowerCase()===wanted)found=true;});if(value&&!found)values.unshift(value);return values.map(function(x){return `<option value='${esc(x)}' ${String(x).toLowerCase()===wanted?'selected':''}>${esc(x)}</option>`;}).join('');};
Editor.prototype.mark=function(){this.dirty=true;var dot=this.root.querySelector('[data-dirty]');if(dot)dot.classList.add('show');};
Editor.prototype.render=function(){if(!this.options){this.root.innerHTML='';return;}var close=this.cfg.standalone?`<button class='sd-btn danger' data-act='close'>关闭</button>`:'';this.root.innerHTML=`<div class='sd-page ${this.cfg.standalone?'standalone':'embedded'}'><header class='sd-head'><div><h2>断面图生成 <small>Preview 10</small></h2></div><div class='sd-actions'><button class='sd-btn' data-act='reset'>恢复默认</button><button class='sd-btn' data-act='save'>保存设置 <span class='sd-dirty' data-dirty>●</span></button><button class='sd-btn primary' data-act='draw'>在图中生成</button>${close}</div></header><div class='sd-work'><div class='sd-editor'>${this.basicCard()}${this.layerCard()}${this.displayCard()}</div>${this.previewCard()}</div><div class='sd-modal-backdrop' data-modal></div></div>`;this.bind();this.drawPreview();};
Editor.prototype.basicCard=function(){var o=this.options;return `<section class='sd-card'><div class='sd-card-head'><h3>基本参数</h3></div><div class='sd-card-body'><div class='sd-fields'><label class='sd-field wide'><span>管段注记</span><textarea data-field='SectionTitle'>${esc(o.SectionTitle||'')}</textarea></label><label class='sd-field'><span>断面宽度 m</span><input type='number' step='0.01' min='0.01' data-field='Width' value='${fmt(o.Width)}'></label><label class='sd-field'><span>文字高度</span><input type='number' step='0.01' min='0.001' data-field='TextHeight' value='${fmt(o.TextHeight)}'></label><label class='sd-field'><span>注记样式</span><select data-field='TextStyleName'>${this.selectOptions(this.catalog.textStyles,o.TextStyleName||'')}</select></label><label class='sd-field'><span>统一图层</span><select data-field='UnifiedLayer'>${this.selectOptions(this.catalog.layerNames,o.BorderLayerName||'0')}</select></label><label class='sd-field'><span>标注样式</span><select data-field='DimensionStyleName'>${this.selectOptions(this.catalog.dimensionStyles,o.DimensionStyleName||'')}</select></label><label class='sd-field'><span>左侧注记宽度</span><input type='number' step='0.01' min='0.2' data-field='LeftLabelWidth' value='${fmt(o.LeftLabelWidth)}'></label><label class='sd-field'><span>总高度 m</span><input type='number' step='0.01' min='0.01' data-field='TotalHeight' value='${fmt(o.TotalHeight)}'></label><label class='sd-field'><span>总高度模式</span><select data-field='LockTotalHeight'><option value='false' ${o.LockTotalHeight?'':'selected'}>按层高自动计算</option><option value='true' ${o.LockTotalHeight?'selected':''}>锁定输入值</option></select></label></div></div></section>`;};
Editor.prototype.layerCard=function(){var self=this,rows=this.options.Layers.map(function(l,i){var pipes=(l.Pipes||[]).length;return `<tr class='sd-layer-row' draggable='true' data-layer-row='${i}'><td class='sd-drag' title='拖拽排序'>⋮⋮</td><td><input type='checkbox' data-layer-field='DrawLayer' ${l.DrawLayer?'checked':''}></td><td><input type='text' data-layer-field='LeftLabel' value='${esc(l.LeftLabel||'')}'></td><td><input type='number' step='0.01' min='0.001' data-layer-field='Height' value='${fmt(l.Height)}'></td><td><input type='checkbox' data-layer-field='HeightLocked' ${l.HeightLocked?'checked':''}></td><td><select data-layer-field='HatchPatternName'>${self.selectOptions(self.catalog.hatchPatterns,l.HatchPatternName||'无填充')}</select></td><td><input type='number' step='0.01' min='0' data-layer-field='HatchScale' value='${fmt(l.HatchScale)}'></td><td><button class='sd-mini' data-act='pipes' data-index='${i}'>管道 ${pipes}</button></td><td><button class='sd-mini danger' data-act='deleteLayer' data-index='${i}'>删除</button></td></tr>`;}).join('');return `<section class='sd-card'><div class='sd-card-head'><h3>结构层</h3><button class='sd-btn' data-act='addLayer'>新增层</button></div><div class='sd-table-wrap'><table class='sd-table'><thead><tr><th></th><th>绘制</th><th>名称</th><th>层高 m</th><th>锁定</th><th>填充图案</th><th>比例</th><th>管道</th><th></th></tr></thead><tbody>${rows}</tbody></table></div></section>`;};
