            script = script.Replace(" · ${layers.length} 层 · ${pipeCount} 管`;", " · ${layers.length} 层 · ${pipeCount} 管 · ×${fmt(o.DrawingScale||1)}`;");
            script = script.Replace("(o.DrawTitle&&o.SectionTitle?num(o.TitleOffset,.12)+.22:.05)", "(o.DrawTitle&&o.SectionTitle?num(o.TitleOffset,.12)+Math.max(.22,String(o.SectionTitle).split(/\\r?\\n/).filter(function(v){return v.trim();}).length*num(o.TextHeight,.08)*1.7):.05)");
            script = script.Replace("if(o.DrawTitle&&o.SectionTitle)s.push(`<text class='title-text' x='${x(width/2)}' y='${y(-(o.DrawBottomDimension?num(o.BottomDimensionOffset,.08):0)-num(o.TitleOffset,.12))}'>${esc(String(o.SectionTitle).replace(/[\\r\\n]+/g,' / '))}</text>`);", "if(o.DrawTitle&&o.SectionTitle){var titleLines=String(o.SectionTitle).replace(/\\r\\n/g,'\\n').replace(/\\r/g,'\\n').split('\\n').filter(function(v){return v.trim();}),titleY=y(-(o.DrawBottomDimension?num(o.BottomDimensionOffset,.08):0)-num(o.TitleOffset,.12)),titleGap=Math.max(18,num(o.TextHeight,.08)*scale*1.35);titleLines.forEach(function(t,ti){s.push(`<text class='title-text' x='${x(width/2)}' y='${titleY+ti*titleGap}'>${esc(t.trim())}</text>`);});}");
            script = script.Replace("var close=this.cfg.standalone?`<button class='sd-btn danger' data-act='close'>关闭</button>`:'';", "var close='';");
            script = script.Replace("<button class='sd-btn' data-act='reset'>恢复默认</button>", string.Empty);
            return script;
        }

        private static string Html(string value)
        {
            if (string.IsNullOrEmpty(value)) return string.Empty;
            return value.Replace("&", "&amp;").Replace("<", "&lt;").Replace(">", "&gt;").Replace("\"", "&quot;").Replace("'", "&#39;");
        }
    }
}
